--- index.html
+++ index.html
@@ -8,4 +8,30 @@
 </style>
 </head>
 <body><main class="shell"><canvas id="game" aria-label="Last Run Blackout game"></canvas><div class="scan"></div><div class="vignette"></div><div class="hud"><div class="top"><div class="brand">LAST RUN <b>// BLACKOUT</b><div class="small">SUBLEVEL 09 · NO EXTRACTION WINDOW</div></div><div class="read">DISTANCE<strong id="dist">0000 <small style="font-size:11px">m</small></strong></div></div><div class="bottom"><div class="status"><div class="label">VITALS</div><div class="hearts" id="hearts"><i class="heart"></i><i class="heart"></i></div></div><div class="status"><div class="label">BLACKOUT PULSE <span id="pulseText">READY</span></div><div class="meter"><i id="pulseBar"></i></div><div class="small">E / X · DISABLE THE HUNT</div></div><div class="read">BEST<strong id="best">0000</strong></div></div></div><div class="touch" id="touch"><button data-action="left">◀</button><button data-action="jump">▲</button><button data-action="slide">▼</button><button data-action="right">▶</button><button data-action="pulse" style="color:#62f5e1">✳</button></div><div class="overlay" id="overlay"><section class="panel"><div class="eyebrow" id="eyebrow">A LAST CHANCE IS STILL A CHANCE</div><h1 id="title">RUN<br><span>OR BLEED.</span></h1><p id="message">The undercity is coming down. The exit is 1,600 meters ahead. The thing behind you does not get tired. Make every step count.</p><div class="keys"><span class="key"><b>A / D</b>LANES</span><span class="key"><b>W / SPACE</b>JUMP</span><span class="key"><b>S</b>SLIDE</span><span class="key"><b>E</b>PULSE</span></div><button class="cta" id="start">[ ENTER THE RUN ]</button><p class="hint">TWO WOUNDS. NO CHECKPOINTS. NO SECOND TRY.</p></section></div></main>
 <script>
+(()=>{
+const c=document.querySelector('#game'),ctx=c.getContext('2d'),$=s=>document.querySelector(s),overlay=$('#overlay');let W=0,H=0,dpr=1;
+function resize(){const r=c.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);W=r.width;H=r.height;ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(resize).observe(c);resize();
+const TARGET=1600,LANES=[-1,0,1],rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+let state='menu',last=0,dist=0,speed=27,score=0,lane=1,visualLane=1,jump=0,slide=0,lives=2,pulse=0,pulseFlash=0,invuln=0,spawn=0,shake=0,obstacles=[],particles=[],streak=0,beat=0,best=+(localStorage.getItem('blackout-best')||0),touchX=null;
+$('#best').textContent=String(best).padStart(4,'0');
+function start(){state='run';dist=0;speed=27;score=0;lane=1;visualLane=1;jump=slide=pulse=pulseFlash=invuln=spawn=shake=streak=0;lives=2;obstacles=[];particles=[];overlay.classList.add('hidden');$('#hearts').innerHTML='<i class="heart"></i><i class="heart"></i>';last=performance.now()}
+$('#start').onclick=start;
+function gameover(win){state=win?'win':'dead';$('#eyebrow').textContent=win?'YOU MADE IT OUT':'RUN TERMINATED';$('#title').innerHTML=win?'THE CITY<br><span>LOST.</span>':'YOU<br><span>BLEED.</span>';$('#message').textContent=win?`Extraction reached. ${Math.floor(score).toLocaleString()} points earned. The city will remember one survivor.`:`You made it ${Math.floor(dist)} meters. The undercity keeps what it catches. Try again. No checkpoints.`;$('#start').textContent='[ RUN IT BACK ]';overlay.classList.remove('hidden');best=Math.max(best,Math.floor(dist));localStorage.setItem('blackout-best',best);$('#best').textContent=String(best).padStart(4,'0')}
+function act(a){if(state!=='run')return;if(a==='left')lane=Math.max(0,lane-1);if(a==='right')lane=Math.min(2,lane+1);if(a==='jump'&&jump<=0&&slide<=0)jump=.82;if(a==='slide'&&jump<=.12)slide=.7;if(a==='pulse'&&pulse<=0){pulse=1;pulseFlash=.9;streak++;for(const o of obstacles)if(o.z<54&&o.z>0&&o.type==='drone')o.stunned=1.5;for(let i=0;i<20;i++)particles.push({x:W/2+rand(-60,60),y:H*.78+rand(-20,20),vx:rand(-180,180),vy:rand(-220,100),life:rand(.3,.8),c:'#62f5e1'})}}
+addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','a','d','w','s','e','x','p','Enter'].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key==='Enter'&&(state!=='run')){start();return}if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')act('left');if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')act('right');if(['ArrowUp',' ','w','W'].includes(e.key))act('jump');if(e.key==='ArrowDown'||e.key.toLowerCase()==='s')act('slide');if(['e','E','x','X'].includes(e.key))act('pulse');if(e.key.toLowerCase()==='p'&&state==='run')state='pause';else if(e.key.toLowerCase()==='p'&&state==='pause'){state='run';last=performance.now()}});
+document.querySelectorAll('.touch button').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();act(b.dataset.action)})});c.addEventListener('pointerdown',e=>touchX=e.clientX);c.addEventListener('pointerup',e=>{if(touchX===null)return;const dx=e.clientX-touchX;if(Math.abs(dx)>35)act(dx<0?'left':'right');else if(e.clientY<H*.65)act('jump');touchX=null});
+function project(z){const t=clamp(1-z/150,0,1.08),y=H*(.31+t*.74),half=(W*.045+t*W*.39);return {t,y,half,x:W/2}}
+function laneX(l,t){return W/2+l*(W*.055+t*W*.255)}
+function poly(points,fill,stroke=null,lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
+function background(dt){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#090a11');sky.addColorStop(.38,'#20151d');sky.addColorStop(1,'#0c0b10');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
+// distant industrial silhouettes
+for(let layer=0;layer<3;layer++){let base=H*(.39+layer*.045),unit=34+layer*20,off=(dist*(.08+layer*.15))%unit;ctx.fillStyle=['#12151c','#17131a','#211117'][layer];for(let x=-unit;x<W+unit;x+=unit){let xx=x-off,h=randStatic(xx+layer*900)*H*(.08+layer*.1);ctx.fillRect(xx,base-h,unit*.7,h);ctx.fillStyle='#ff35401c';ctx.fillRect(xx+unit*.12,base-h*.7,2,2)}}
+let horizon=H*.34;ctx.fillStyle='#ff273014';ctx.fillRect(0,horizon-2,W,2);
+// rails / converging lane markings
+for(let i=-2;i<=2;i++){let xb=W/2+i*W*.36,xt=W/2+i*W*.055;ctx.strokeStyle=i===-1||i===1?'#a4474938':'#ffb15625';ctx.lineWidth=i===0?2:1;ctx.beginPath();ctx.moveTo(xt,horizon);ctx.lineTo(xb,H*1.04);ctx.stroke()}
+let off=(dist*2.7)%70;for(let i=0;i<10;i++){let z=i*70-off,p=project(z);ctx.strokeStyle=`rgba(255,83,62,${.04+p.t*.18})`;ctx.lineWidth=1+p.t*3;ctx.beginPath();ctx.moveTo(W/2-p.half,p.y);ctx.lineTo(W/2+p.half,p.y);ctx.stroke()}
+// side warning lamps
+for(let side of [-1,1])for(let i=0;i<5;i++){let z=(i*100+80-dist*1.5%100);if(z<0)z+=500;let p=project(z);ctx.fillStyle=(i+Math.floor(dist/12))%3===0?'#ff3e53':'#453038';ctx.shadowBlur=12;ctx.shadowColor='#ff3344';ctx.fillRect(W/2+side*(p.half+8),p.y-3,3+p.t*5,3+p.t*5);ctx.shadowBlur=0}
+}
+function randStatic(x){let n=Math.sin(x*12.9898)*43758.5453;return n-Math.floor(n)}

