function randStatic(x){let n=Math.sin(x*12.9898)*43758.5453;return n-Math.floor(n)}
function spawnHazard(){let type;const r=Math.random();type=r<.34?'spike':r<.61?'beam':r<.84?'drone':'block';const l=Math.floor(Math.random()*3);obstacles.push({type,lane:l,z:rand(78,100),stunned:0,seed:Math.random()});if(dist>330&&Math.random()<.25)obstacles.push({type:Math.random()<.5?'spike':'beam',lane:(l+1+Math.floor(Math.random()*2))%3,z:rand(84,101),stunned:0,seed:Math.random()})}
function drawObstacle(o){const p=project(o.z);if(o.z<0||o.z>155)return;let x=laneX(o.lane,p.t),s=.25+p.t*1.35;ctx.save();ctx.translate(x,p.y);if(o.type==='drone'){ctx.fillStyle=o.stunned>0?'#62f5e1':'#c92f43';ctx.shadowColor=o.stunned>0?'#62f5e1':'#ff203c';ctx.shadowBlur=14*s;ctx.beginPath();ctx.ellipse(0,-22*s,19*s,8*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffe2c4';ctx.fillRect(-3*s,-25*s,6*s,3*s);ctx.strokeStyle='#ff4d55';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(-17*s,-19*s);ctx.lineTo(-24*s,-8*s);ctx.moveTo(17*s,-19*s);ctx.lineTo(24*s,-8*s);ctx.stroke()}else if(o.type==='spike'){poly([[-27*s,0],[0,-40*s],[27*s,0]],'#a52a38','#ff5260',2*s);poly([[-10*s,-5*s],[0,-29*s],[10*s,-5*s]],'#ff5962');ctx.fillStyle='#e65d50';ctx.fillRect(-30*s,-3*s,60*s,5*s)}else if(o.type==='beam'){ctx.fillStyle='#28171d';ctx.fillRect(-34*s,-38*s,68*s,34*s);ctx.fillStyle='#ff394e';ctx.fillRect(-37*s,-39*s,74*s,7*s);for(let i=-2;i<3;i++){ctx.fillStyle='#f6aa5b';ctx.fillRect(i*14*s,-20*s,7*s,4*s)}}else{ctx.fillStyle='#29151a';ctx.fillRect(-35*s,-58*s,70*s,58*s);ctx.fillStyle='#ff4053';ctx.fillRect(-37*s,-57*s,74*s,8*s);ctx.fillStyle='#ffb05f';ctx.fillRect(-6*s,-37*s,12*s,5*s)}ctx.restore()}
function drawRunner(){visualLane+=(lane-visualLane)*.22;let x=laneX(visualLane,.93),ground=H*.88,air=jump>0?Math.sin((.82-jump)/.82*Math.PI)*H*.19:0;let y=ground-air;ctx.save();if(invuln>0&&Math.floor(invuln*18)%2===0)ctx.globalAlpha=.35;
// shadow
ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(x,ground+7,22+(air?8:0),6,0,0,Math.PI*2);ctx.fill();
// runner silhouette
ctx.translate(x,y);let crouch=slide>0?.55:1;ctx.scale(1,crouch);ctx.fillStyle='#d2c5bc';ctx.fillRect(-9,-47,18,28);ctx.fillStyle='#ff4053';ctx.fillRect(-11,-25,22,8);ctx.fillStyle='#17171c';ctx.fillRect(-8,-18,7,18);ctx.fillRect(2,-18,7,18);ctx.fillStyle='#ddd0c2';ctx.beginPath();ctx.arc(0,-55,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#17171c';ctx.fillRect(-8,-59,17,5);ctx.strokeStyle='#e5c4a0';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-8,-40);ctx.lineTo(-17,-29+Math.sin(beat*15)*3);ctx.moveTo(8,-40);ctx.lineTo(16,-34-Math.sin(beat*15)*3);ctx.stroke();ctx.restore();
if(pulseFlash>0){ctx.strokeStyle=`rgba(98,245,225,${pulseFlash})`;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x,ground+8,80+(1-pulseFlash)*260,30+(1-pulseFlash)*70,0,0,Math.PI*2);ctx.stroke()}}
function drawFx(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt;p.life-=dt;ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.c;ctx.fillRect(p.x,p.y,3,3);if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1}
function update(dt){beat+=dt; if(state!=='run')return;dist+=speed*dt;speed=Math.min(43,27+dist*.006);score+=dt*100+(speed-27)*dt*6;spawn-=dt;if(spawn<=0){spawnHazard();spawn=Math.max(.56,rand(1.02,1.42)-(speed-27)*.017)}
for(const o of obstacles){o.z-=speed*dt;if(o.stunned>0)o.stunned-=dt}obstacles=obstacles.filter(o=>o.z>-12);jump=Math.max(0,jump-dt);slide=Math.max(0,slide-dt);invuln=Math.max(0,invuln-dt);pulseFlash=Math.max(0,pulseFlash-dt*1.1);if(pulse>0)pulse=Math.max(0,pulse-dt);if(shake>0)shake=Math.max(0,shake-dt*20);
// pulse's active second freezes hunter drones and stretches the hazard window; cooldown lasts eight seconds.
for(const o of obstacles){if(o.z<4&&o.z>-2&&o.lane===lane&&invuln<=0){let safe=o.stunned>0||(pulse>7.05&&o.type==='drone')||(o.type==='spike'&&jump>.22)||(o.type==='beam'&&slide>.16);if(!safe){lives--;invuln=1.35;shake=11;score=Math.max(0,score-150);o.z=-14;$('#hearts').children[lives]?.classList.add('empty');for(let i=0;i<18;i++)particles.push({x:W/2+rand(-30,30),y:H*.8,vx:rand(-200,200),vy:rand(-220,40),life:rand(.2,.6),c:'#ff4053'});if(lives<=0){gameover(false);return}}else{o.z=-14;score+=60;streak++;if(streak%5===0)pulse=Math.max(0,pulse-1)}}}
if(dist>=TARGET){gameover(true);return}$('#dist').innerHTML=String(Math.floor(dist)).padStart(4,'0')+' <small style="font-size:11px">m</small>';$('#pulseBar').style.width=`${Math.max(0,100-pulse/8*100)}%`;$('#pulseText').textContent=pulse<=0?'READY':pulse>7.05?'ACTIVE':`${pulse.toFixed(1)}s`;}

